function maxProfit(k: number, prices: number[]): number {
  const n = prices.length;

  // Если k >= n / 2, ограничение на число сделок не мешает:
  // берём каждый рост цены (как в Stock II)
  if (k >= Math.floor(n / 2)) {
    let profit = 0;
    for (let i = 1; i < n; i++) {
      profit += Math.max(0, prices[i] - prices[i - 1]);
    }
    return profit;
  }

  // buy[j]  — лучший баланс, если держим акцию в j-й сделке
  // sell[j] — лучший баланс после завершения j сделок
  const buy: number[] = new Array(k + 1).fill(-Infinity);
  const sell: number[] = new Array(k + 1).fill(0);

  for (const p of prices) {
    for (let j = 1; j <= k; j++) {
      // j-я покупка делается на деньги после j - 1 завершённых сделок
      buy[j] = Math.max(buy[j], sell[j - 1] - p);
      // j-я продажа закрывает j-ю покупку
      sell[j] = Math.max(sell[j], buy[j] + p);
    }
  }

  // sell не убывает по j, поэтому максимум — в sell[k]
  return sell[k];
}

// Время: O(n · k) (или O(n), если k >= n / 2)
// Память: O(k)
